"""usage: python3 tools/target/mk_briefs.py <t> "<LANG>" ["extra note for every writer"]
Writes docs/briefs/en-<t>-{A,B,1,2,3,R}.md from tools/target/<t>/profile.json (deck halves, three lesson files, reviewer)."""
import json, sys, os
T, LANG = sys.argv[1], sys.argv[2]; NOTE = sys.argv[3] if len(sys.argv) > 3 else ''
import os
R = os.environ.get('LANGAPP_ROOT') or os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')); j = json.load(open('%s/tools/target/%s/profile.json' % (R, T), encoding='utf8'))
ids = [l['id'] for l in j['lessons']]; dk = [d['name'] for d in j['decks']]; h = (len(dk) + 1) // 2; n = len(ids); a = (n + 2) // 3; b = a + (n - a + 1) // 2
tool = os.path.exists('%s/tools/target/%s/respell.js' % (R, T))
roles = {'A': ('decks-a.js and extra-a.js', 'the first %d decks in profile order: %s' % (h, ' · '.join(dk[:h])), 'D'), 'B': ('decks-b.js and extra-b.js', 'the last %d decks in profile order: %s' % (len(dk) - h, ' · '.join(dk[h:])), 'D'),
         '1': ('lessons-1.js', 'lessons ' + ' · '.join(ids[:a]), 'L'), '2': ('lessons-2.js', 'lessons ' + ' · '.join(ids[a:b]), 'L'), '3': ('lessons-3.js', 'lessons ' + ' · '.join(ids[b:]), 'L')}
pron = ("PRON: never hand-write a pronunciation. Generate every `pron` with `node tools/target/%s/respell.js \"<%s text>\"` (or `require` it in a small script of your own) and paste the output unchanged. If the tool's result is wrong for a string, do NOT edit the tool (other writers are using it): keep the tool's output in your file and list the string with the pron you believe is right in your report, so the lead can add it to the tool's lexicon and regenerate.\n\n" % (T, LANG)) if tool else "PRON: follow the profile's §6 format exactly; the validator checks `pronPattern` and that the same string has the same pron everywhere.\n\n"
for r, (files, scope, kind) in roles.items():
    txt = "You are EN-%s-%s, one of five writers of the Lang App course \"%s for English speakers\" (`en-%s`) in /home/claude.\n\nRead first, fully: `/home/claude/docs/TARGET-BRIEF.md` (the shared writer brief, with `<t>` = `%s` and `<LANG>` = %s — binding), `/home/claude/docs/profiles/en-%s.md` (style authority: variant, register, glossary, error zones, pron policy, standing rule, the per-lesson and per-deck notes with sample cards), `/home/claude/tools/target/%s/profile.json`, `/home/claude/tools/target/lib.js` (header: the practice shorthand), `/home/claude/docs/PRACTICE-SPEC.md`, the last section of `/home/claude/docs/PHASE2-BRIEF.md` (recurring problems), and — as a finished model of the SHAPE and level only, not to translate — the matching file of the Spanish pilot in `/home/claude/tools/target/es/` (%s).\n\nYOU OWN: `tools/target/%s/%s` — %s. Create the file(s); touch no other file.\n\n" % (T.upper(), r, LANG, T, T, LANG, T, T, 'decks-a.js and extra-a.js' if kind == 'D' else 'lessons-1.js', T, files, scope)
    txt += pron
    if kind == 'D': txt += "DECKS: 16–18 cards per deck, at the level and tone of the profile's sample cards (include the samples). A card's `target` is one phrase or sentence a learner will actually say or hear; single words only in vocabulary-style decks, and then with their article so gender is learned with the noun. No target appears in two decks (the other deck writer owns the other half: do not duplicate obvious phrases from decks outside your list — check the profile's samples for those decks). EXTRA: at least 3 dialogues and 2 examples per deck for your cards, and 9 patterns in total.\n"
    else: txt += "LESSONS: write each lesson exactly as the profile's §8 note for it describes, linked to the deck profile.json names. Earlier lessons are prerequisites: use only grammar the course has taught up to your lesson (the profile's order), and vocabulary a beginner would know by then or that the item supplies. A word-order item must have exactly ONE correct order with its tiles: if a time or place phrase could move, or the subject could sit on either side of the verb, cue the prompt or choose another sentence. A variant that is normal somewhere in the language's region is never a 'wrong' option without saying where it is not used. The decks are being written at the same time by other writers; you do not need their cards.\n"
    if NOTE: txt += '\n' + NOTE + '\n'
    txt += "\nThen check and report as TARGET-BRIEF says.\n"
    open('%s/docs/briefs/en-%s-%s.md' % (R, T, r), 'w', encoding='utf8').write(txt)
rv = "You are EN-%s-REVIEWER on the Lang App project in /home/claude: the cold reviewer of the course \"%s for English speakers\" (`en-%s`). Your complete instructions are `/home/claude/docs/TARGET-REVIEW.md` with `<t>` = `%s` and `<LANG>` = %s. Read it in full and carry it out.\n\n" % (T.upper(), LANG, T, T, LANG)
if tool: rv += "Every `pron` in this course is generated by `node tools/target/%s/respell.js \"<text>\"`: when you change a string that has a pron, regenerate it with the tool and paste the output unchanged; if the tool is wrong for a string, add the string to the tool's exceptions lexicon (you are the only one editing now) and regenerate every pron that contains it.\n" % T
open('%s/docs/briefs/en-%s-R.md' % (R, T), 'w', encoding='utf8').write(rv)
print(T, 'lessons', len(ids[:a]), len(ids[a:b]), len(ids[b:]), 'decks', h, len(dk) - h, 'tool', tool)
